        return false;

      if (!(x.rtgMaxDischargeRateW () == y.rtgMaxDischargeRateW ()))
        return false;

      if (!(x.rtgMaxV () == y.rtgMaxV ()))
        return false;

      if (!(x.rtgMaxVA () == y.rtgMaxVA ()))
        return false;

      if (!(x.rtgMaxVar () == y.rtgMaxVar ()))
        return false;

      if (!(x.rtgMaxVarNeg () == y.rtgMaxVarNeg ()))
        return false;

      if (!(x.rtgMaxW () == y.rtgMaxW ()))
        return false;

      if (!(x.rtgMaxWh () == y.rtgMaxWh ()))
        return false;

      if (!(x.rtgMinPFOverExcited () == y.rtgMinPFOverExcited ()))
        return false;

      if (!(x.rtgMinPFUnderExcited () == y.rtgMinPFUnderExcited ()))
        return false;

      if (!(x.rtgMinV () == y.rtgMinV ()))
        return false;

      if (!(x.rtgNormalCategory () == y.rtgNormalCategory ()))
        return false;

      if (!(x.rtgOverExcitedPF () == y.rtgOverExcitedPF ()))
        return false;

      if (!(x.rtgOverExcitedW () == y.rtgOverExcitedW ()))
        return false;

      if (!(x.rtgReactiveSusceptance () == y.rtgReactiveSusceptance ()))
        return false;

      if (!(x.rtgUnderExcitedPF () == y.rtgUnderExcitedPF ()))
        return false;

      if (!(x.rtgUnderExcitedW () == y.rtgUnderExcitedW ()))
        return false;

      if (!(x.rtgVNom () == y.rtgVNom ()))
        return false;

      if (!(x.type () == y.type ()))
        return false;

      if (!(x.doeModesSupported () == y.doeModesSupported ()))
        return false;

      return true;
